enum class Level(val weight: Int) { LOW(1), MEDIUM(5), HIGH(10) }

sealed interface Result {
    data class Ok(val value: String) : Result
    data class Error(val message: String, val code: Int) : Result
    data object Loading : Result
}

fun render(r: Result): String = when (r) {        // exhaustive, no else
    is Result.Ok -> "value: ${r.value}"           // smart cast
    is Result.Error if r.code >= 500 -> "server error: ${r.message}" // guard (2.2)
    is Result.Error -> "error ${r.code}"
    Result.Loading -> "loading..."
}

fun main() {
    println(Level.entries.map { it.name })        // [LOW, MEDIUM, HIGH]
    println(Level.valueOf("HIGH").weight)         // 10
    println(Level.MEDIUM > Level.LOW)             // true (by ordinal)

    listOf(Result.Ok("42"), Result.Error("db down", 503), Result.Error("nope", 404), Result.Loading)
        .forEach { println(render(it)) }
    // value: 42 / server error: db down / error 404 / loading...
}

import java.io.StringReader

fun parsePort(s: String): Int {
    val n = s.toIntOrNull() ?: throw IllegalArgumentException("not a number: $s")
    require(n in 1..65535) { "port out of range: $n" }
    return n
}

fun main() {
    val port = try { parsePort("80x") } catch (e: IllegalArgumentException) {
        println(e.message)                  // not a number: 80x
        8080
    }
    println(port)                           // 8080

    val r: Result<Int> = runCatching { parsePort("70000") }
    println(r.isFailure)                    // true
    println(r.exceptionOrNull()?.message)   // port out of range: 70000
    println(runCatching { parsePort("443") }.getOrElse { -1 }) // 443

    val first = StringReader("line1\nline2").buffered().use { it.readLine() }
    println(first)                          // line1 (reader closed)
    var started = false
    runCatching { check(started) { "not started" } }.onFailure { println(it.message) } // not started
}

open class Animal(val name: String)
class Cat(name: String) : Animal(name)

class Producer<out T>(private val item: T) { fun get(): T = item }
class Consumer<in T> { fun accept(x: T) = println("accepted $x") }

fun <T : Comparable<T>> maxOf3(a: T, b: T, c: T): T = maxOf(a, maxOf(b, c))

inline fun <reified T> List<Any>.only(): List<T> = filterIsInstance<T>()

fun names(xs: List<*>) = xs.map { it.toString() }   // star projection

fun main() {
    val cats: Producer<Cat> = Producer(Cat("Tom"))
    val animals: Producer<Animal> = cats             // OK: covariant
    println(animals.get().name)                      // Tom

    val anyConsumer = Consumer<Any>()
    val strConsumer: Consumer<String> = anyConsumer  // OK: contravariant
    strConsumer.accept("hi")                         // accepted hi
    println(maxOf3(3, 9, 4))                         // 9
    println(listOf(1, "a", 2.5, "b").only<String>()) // [a, b]
    println(names(listOf(1, null)))                  // [1, null]
    // val bad: MutableList<Any> = mutableListOf<String>()  // error: invariant
}

