import kotlinx.coroutines.*
import kotlin.system.measureTimeMillis

suspend fun fetchUser(): String { delay(300); return "Ada" }        // simulated I/O
suspend fun fetchScore(user: String): Int { delay(300); return user.length * 10 }

fun main() = runBlocking {
    val seq = measureTimeMillis {
        val user = fetchUser()
        println("$user ${fetchScore(user)}")       // Ada 30
    }
    println("sequential ~${seq / 100 * 100} ms")    // sequential ~600 ms
    val par = measureTimeMillis {
        val a = async { fetchScore("Ada") }          // both start now
        val b = async { fetchScore("Grace") }
        println(a.await() + b.await())             // 80
    }
    println("concurrent ~${par / 100 * 100} ms")    // concurrent ~300 ms
    val job = launch { repeat(3) { i -> println("tick $i"); delay(50) } }
    job.join()                                     // tick 0 / tick 1 / tick 2
    val jobs = List(10_000) { launch { delay(100) } } // cheap: 10k coroutines
    jobs.joinAll()
    println("done")
}

import kotlinx.coroutines.*
suspend fun loadAll(): List<String> = coroutineScope {
    val a = async { delay(100); "a" }
    val b = async { delay(50); error("b failed") }   // fails -> cancels a and the scope
    listOf(a.await(), b.await())
}
fun main() = runBlocking {
    runCatching { loadAll() }.onFailure { println("caught: ${it.message}") } // caught: b failed
    val text = withContext(Dispatchers.IO) {          // blocking work off the caller's thread
        Thread.currentThread().name.startsWith("DefaultDispatcher")
    }
    println(text)                                     // true
    val result = withTimeoutOrNull(120) {
        var i = 0
        while (true) { ensureActive(); i++; delay(50) }  // cooperative loop
    }
    println(result)                                   // null (timed out)
    supervisorScope {
        val bad = launch(CoroutineExceptionHandler { _, e -> println("handled: ${e.message}") }) {
            error("boom")
        }
        val good = launch { delay(50); println("sibling still ran") }
        joinAll(bad, good)                            // handled: boom / sibling still ran
    }
}

import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

fun ticker(n: Int): Flow<Int> = flow {
    for (i in 1..n) { delay(50); emit(i) }
}

fun main() = runBlocking {
    ticker(5)
        .filter { it % 2 == 1 }
        .map { it * it }
        .onEach { print("[$it] ") }
        .collect()                                // [1] [9] [25]
    println()
    println(ticker(3).toList())                   // [1, 2, 3]
    val failing = flow { emit(1); error("boom") }
    failing.catch { emit(-1) }.collect { print("$it ") } // 1 -1
    println()
    val state = MutableStateFlow(0)
    val watcher = launch { state.collect { println("state=$it") } }
    delay(10); state.value = 1; delay(10)
    state.value = 1                                // same value: not re-emitted
    state.value = 2; delay(10)
    watcher.cancel()                               // state=0 / state=1 / state=2
}

import kotlin.properties.Delegates
import kotlin.properties.ReadWriteProperty
import kotlin.reflect.KProperty
class Trimmed : ReadWriteProperty<Any?, String> {
    private var value = ""
    override fun getValue(thisRef: Any?, property: KProperty<*>) = value
    override fun setValue(thisRef: Any?, property: KProperty<*>, value: String) { this.value = value.trim() }
}
class Profile(data: Map<String, Any?>) {
    val name: String by data                  // read from the map by property name
    val slug: String by lazy { println("computing"); name.lowercase() }
    var status: String by Delegates.observable("new") { _, old, new -> println("$old -> $new") }
    var bio: String by Trimmed()
}
class CountingSet<T>(private val inner: MutableSet<T> = HashSet()) : MutableSet<T> by inner {
    var attempts = 0; override fun add(element: T): Boolean { attempts++; return inner.add(element) }
}
fun main() {
    val p = Profile(mapOf("name" to "Ada"))
    println(p.slug); println(p.slug)          // computing / ada / ada
    p.status = "active"                       // new -> active
    p.bio = "  likes math  "; println("[${p.bio}]") // [likes math]
    val s = CountingSet<Int>(); s.add(1); s.add(1)
    println("${s.size} ${s.attempts}")        // 1 2
}

@JvmInline value class UserId(val raw: Long) { init { require(raw > 0) } }
@JvmInline value class OrderId(val raw: Long)

fun loadUser(id: UserId) = "user #${id.raw}"

inline fun <T> timed(label: String, block: () -> T): T {
    val start = System.nanoTime()
    return block().also { println("$label took ${(System.nanoTime() - start) / 1_000_000} ms") }
}
inline fun runTwice(crossinline action: () -> Unit) {
    val r = Runnable { action() }                 // called from another context
    r.run(); r.run()
}
fun firstNegative(xs: List<Int>): Int? {
    xs.forEach { if (it < 0) return it }          // non-local return (forEach is inline)
    return null
}
fun main() {
    println(loadUser(UserId(42)))                 // user #42
    // loadUser(OrderId(42))                      // compile error: wrong type
    val sum = timed("sum") { (1..1000).sum() }    // sum took N ms
    println(sum)                                  // 500500
    runTwice { print("x") }; println()            // xx
    println(firstNegative(listOf(3, -1, -5)))     // -1
}

@DslMarker annotation class HtmlDsl

@HtmlDsl abstract class Tag(val name: String) {
    val children = mutableListOf<Any>()
    override fun toString() = "<$name>${children.joinToString("")}</$name>"
}
class Html : Tag("html") { fun body(init: Body.() -> Unit) { children += Body().apply(init) } }
class Body : Tag("body") {
    fun p(init: P.() -> Unit) { children += P().apply(init) }
    fun ul(vararg items: String) { children += Ul().apply { items.forEach { +it } } }
}
class P : Tag("p") { operator fun String.unaryPlus() { children += this } }
class Ul : Tag("ul") { operator fun String.unaryPlus() { children += "<li>$this</li>" } }

fun html(init: Html.() -> Unit): Html = Html().apply(init)
fun main() {
    val page = html {
        body {
            p { +"Hello, DSL" }
            ul("one", "two")
            // p { body { } }    // error thanks to @DslMarker
        }
    }
    println(page) // <html><body><p>Hello, DSL</p><ul><li>one</li><li>two</li></ul></body></html>
}

import kotlin.coroutines.*

// A minimal coroutine runtime, no kotlinx.coroutines needed
var saved: Continuation<String>? = null

suspend fun waitForValue(): String = suspendCoroutine { cont ->
    println("suspending")
    saved = cont                  // keep "the rest of the computation"
}

suspend fun program(): Int {
    val a = waitForValue()        // state 0 -> 1
    println("resumed with $a")
    val b = waitForValue()        // state 1 -> 2
    return (a + b).length
}

fun main() {
    val done = Continuation<Int>(EmptyCoroutineContext) { println("finished: ${it.getOrNull()}") }
    ::program.startCoroutine(done)            // suspending
    println("main thread is free")            // main thread is free
    saved!!.resume("hello")                   // resumed with hello / suspending
    saved!!.resume("!!")                      // finished: 7
}
